def max_hist_area(heights):
    h = list(heights)
    h.append(0)  # Append a dummy zero to trigger the remaining elements
    stack = []
    max_area = 0
    for i, h_val in enumerate(h):
        while stack and h[stack[-1]] > h_val:
            height = h[stack.pop()]
            if stack:
