import sys

class Node:
    def __init__(self, value):
        self.value = value
        self.prev = None
        self.next = None

def main():
    input = sys.stdin.read().splitlines()
    n = int(input[0])
    commands = input[1:n+1]

    head = None
    tail = None

    for cmd in commands:
        parts = cmd.split()
        if parts[0] == 'insert':
            x = int(parts[1])
            new_node = Node(x)
            if head is None:
                head = tail = new_node
            else:
                new_node.next = head
                head.prev = new_node
                head = new_node
        elif parts[0] == 'delete':
            x = int(parts[1])
            current = head
            while current is not None:
                if current.value == x:
                    prev_node = current.prev
                    next_node = current.next
                    if prev_node is not None:
                        prev_node.next = next_node
                    else:
                        head = next_node
                    if next_node is not None:
                        next_node.prev = prev_node
                    else:
                        tail = prev_node
                    break
                current = current.next
        elif parts[0] == 'deleteFirst':
            if head is not None:
                next_node = head.next
                if next_node is not None:
                    next_node.prev = None
                else:
                    tail = None
                head = next_node
        elif parts[0] == 'deleteLast':
            if tail is not None:
                prev_node = tail.prev
                if prev_node is not None:
                    prev_node.next = None
                else:
                    head = None
                tail = prev_node

    result = []
    current = head
    while current is not None:
        result.append(str(current.value))
        current = current.next
    print(' '.join(result))

if __name__ == '__main__':
    main()

